다음 C언어 코드를 실행했을 때 출력되는 결과를 적으시오.

```c
#include <stdio.h>
#include <stdlib.h>
typedef struct Node {
    int data;
    struct Node *left, *right;
} Node;
Node* create(int data) {
    Node* n = malloc(sizeof(Node));
    if (!n) exit(1);
    n->data = data;
    n->left = n->right = NULL;
    return n;
}
void toArray(Node* root, int arr[], int* idx) {
    if (!root) return;
    arr[(*idx)++] = root->data;
    toArray(root->left, arr, idx);
    toArray(root->right, arr, idx);
}
int compare(const void* a, const void* b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);
}
Node* toBST(int arr[], int start, int end) {
    if (start > end) return NULL;
    int mid = (start + end) / 2;
    Node* root = create(arr[mid]);
    root->left = toBST(arr, start, mid - 1);
    root->right = toBST(arr, mid + 1, end);
    return root;
}
void inorder(Node* root) {
    if (!root) return;
    inorder(root->left);
    printf("%d", root->data);
    inorder(root->right);
}
int main() {
    Node* root = create(4);
    root->left = create(7);
    root->right = create(2);
    root->left->left = create(6);
    root->left->right = create(1);
    root->right->left = create(5);
    root->right->right = create(3);
    int arr[7], idx = 0;
    toArray(root, arr, &idx);
    qsort(arr, idx, sizeof(int), compare);
    Node* bst = toBST(arr, 0, idx - 1);
    inorder(bst);
    return 0;
}
```
